  "employeeExpenses.description": "स्पष्ट मदों वाला दावा बनाएँ और स्वतंत्र जाँचकर्ता को भेजें। वित्तीय एकीकरण नीति स्वीकृत होने तक मंज़ूर दावा भुगतान के लिए तैयार रहता है।",
