  "publicPlans.journey.newTitle": "पहली बार आए हैं?",
  "publicPlans.journey.newBody": "प्रस्तावों की तुलना करके पंजीकरण के लिए योजना चुनें या बिना योजना के खाता बनाएँ। केवल पंजीकरण से सशुल्क सदस्यता सक्रिय नहीं होती।",
  "publicPlans.journey.existingTitle": "पहले से खाता है?",
  "publicPlans.journey.existingBody": "अपनी वास्तविक व्यवसाय सदस्यता देखने के लिए लॉगिन करें। पहले से लॉगिन हैं तो सदस्यता पृष्ठ खोलें; देखना और बदलाव करना आपकी अनुमतियों पर निर्भर है।",
  "publicPlans.featuresTitle": "सुविधाएँ और सीमाएँ साथ-साथ",
  "publicPlans.featuresScope": "यहाँ केवल पृष्ठ {page} पर लोड हुए {count} प्रस्तावों की सुविधाएँ हैं। दूसरे पृष्ठों पर अलग प्रस्ताव हो सकते हैं।",
  "publicPlans.featuresCaption": "हर प्रस्ताव की शामिल और वैकल्पिक सुविधाएँ। शून्य वास्तविक सीमा है, असीमित नहीं। वैकल्पिक मॉड्यूल शुल्क प्रति अवधि योजना की मुद्रा में, कर से पहले है।",
  "publicPlans.listingScope": "ये केवल सार्वजनिक प्रस्ताव हैं, आपकी सदस्यता का विवरण नहीं। किसी योजना का गायब या छिपा होना मौजूदा सदस्यता रद्द होने का अर्थ नहीं है।",
  "publicPlans.catalogLimit": "सार्वजनिक सूची के केवल पहले {pages} पृष्ठ देख सकते हैं। ये सभी योजनाएँ नहीं हैं; अपने खाते के विकल्प देखने के लिए लॉगिन करें।",
  "publicPlans.loginPlan": "खाता है? समीक्षा के लिए चुनें",
  "publicPlans.selectionStorage": "योजना चयन के लिंक समीक्षा के लिए आपकी पसंद साथ ले जाते हैं, कीमत आरक्षित नहीं करते। अगर आप चयन के बिना किसी दूसरे लिंक से आगे बढ़ें तो खाते में दोबारा चुनना पड़ सकता है।",
  "publicPlans.emptyTitle": "अभी कोई सार्वजनिक प्रस्ताव नहीं",
  "publicPlans.emptyDescription": "सूची में अभी कोई सार्वजनिक प्रस्ताव नहीं है। व्यवसाय के विकल्प देखने के लिए खाता बनाएँ या लॉगिन करें; इससे मौजूदा सदस्यता की स्थिति तय नहीं होती।",
  "publicPlans.benefitsTitle": "किराना दुकान के लिए चुन रहे हैं?",
  "publicPlans.benefitsEyebrow": "चुनने से पहले दुकान की ज़रूरतें देखें",
  "publicPlans.benefitsDescription": "ये बिंदु तुलना के लिए हैं, हर योजना में इन मॉड्यूल का वादा नहीं। वास्तव में शामिल सुविधाएँ प्रस्ताव कार्ड और सुविधा स्तंभ दिखाते हैं।",
  "publicPlans.benefit.oneTitle": "काउंटर पर बिक्री",
  "publicPlans.benefit.oneBody": "प्रस्ताव में पॉइंट ऑफ सेल और बिक्री मॉड्यूल, प्रति अवधि दस्तावेज़ सीमा और उपलब्ध अतिरिक्त दस्तावेज़ शुल्क देखें।",
  "publicPlans.benefit.twoTitle": "वस्तुएँ और स्टॉक की आवाजाही",
  "publicPlans.benefit.twoBody": "स्टॉक और खरीद मॉड्यूल देखें: शामिल, वैकल्पिक या अनुपलब्ध? एक मॉड्यूल जोड़ने से उसकी सभी आवश्यकताएँ शामिल नहीं होतीं।",
  "publicPlans.benefit.threeTitle": "दुकान की टीम",
  "publicPlans.benefit.threeBody": "उपयोगकर्ता और कर्मचारी सीमाओं की अलग तुलना करें। सदस्यता उपलब्ध मॉड्यूल तय करती है; हर कर्मचारी की अनुमतियाँ तय करती हैं कि वह क्या उपयोग कर सकता है।",
  "publicPlans.operator.preview": "प्रदर्शन से पहले सामग्री, कर और अतिरिक्त सुविधाएँ देखें",
