  "publicPlans.operator.prepare": "नाम, विवरण, कीमतें, मुद्राएँ, कर, सीमाएँ और मॉड्यूल जाँचें। सार्वजनिक सामग्री में आंतरिक जानकारी या ग्राहकों के नाम न रखें।",
